using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;
public static class TestGroveWalk {
 static Keyboard keyboard;static Rigidbody2D body;static Transform player;static ForestNavigation nav;static EnemySpawner spawner;static AshenFrontierEncounterController[] encounters;static Vector2 original;static float z;static int leg,index,frames;static double begin,lastProgress;static Vector2 last;static List<Vector2> path=new List<Vector2>();static List<string> results=new List<string>();
 static Vector2[] targets={new Vector2(-27,8),new Vector2(-24.5f,15.5f),new Vector2(-27,16),new Vector2(-22,19),new Vector2(-23,21),new Vector2(-15,21),new Vector2(-12,17),new Vector2(-12,11),new Vector2(-16,6.5f),new Vector2(-23,7),new Vector2(-27,2)};
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play mode required");player=GameObject.Find("Player").transform;body=player.GetComponent<Rigidbody2D>();original=body.position;z=Camera.main.transform.position.z;nav=UnityEngine.Object.FindAnyObjectByType<ForestNavigation>();spawner=UnityEngine.Object.FindAnyObjectByType<EnemySpawner>();encounters=UnityEngine.Object.FindObjectsByType<AshenFrontierEncounterController>(FindObjectsInactive.Exclude);foreach(var e in encounters)e.enabled=false;spawner.enabled=false;foreach(var e in EnemyController.ActiveControllers.ToArray())if(e)e.gameObject.SetActive(false);
 body.position=new Vector2(-27,2);player.position=new Vector3(-27,2,0);Physics2D.SyncTransforms();nav.Invalidate();keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();leg=0;index=0;frames=0;begin=EditorApplication.timeSinceStartup;lastProgress=begin;last=body.position;Plan();InputSystem.onAfterUpdate+=Input;EditorApplication.update+=Tick;return "Started real Input System / Rigidbody2D traversal of 11 route legs. Enemies temporarily disabled only for isolated movement testing.";}
 static void Plan(){path.Clear();nav.Invalidate();if(!nav.Find(body.position,targets[leg],path,true)){Finish("FAIL no route to "+targets[leg]);return;}index=0;lastProgress=EditorApplication.timeSinceStartup;}
 static void Input(){if(InputState.currentUpdateType!=InputUpdateType.Dynamic||keyboard==null||!body)return;keyboard.MakeCurrent();var keys=new List<Key>();if(index<path.Count){var d=path[index]-body.position;if(d.x>.08f)keys.Add(leg%2==0?Key.D:Key.RightArrow);else if(d.x<-.08f)keys.Add(leg%2==0?Key.A:Key.LeftArrow);if(d.y>.08f)keys.Add(leg%2==0?Key.W:Key.UpArrow);else if(d.y<-.08f)keys.Add(leg%2==0?Key.S:Key.DownArrow);}InputState.Change(keyboard,new KeyboardState(keys.ToArray()));}
 static void Tick(){if(!Application.isPlaying||!body){Finish("FAIL Play stopped");return;}frames++;if(Mathf.Abs(Camera.main.transform.position.z-z)>.001f){Finish("FAIL camera Z changed");return;}var now=EditorApplication.timeSinceStartup;if(Vector2.Distance(last,body.position)>.1f){last=body.position;lastProgress=now;}while(index<path.Count&&Vector2.Distance(body.position,path[index])<.18f)index++;
 if(index>=path.Count){results.Add("PASS actual keyboard/physics leg "+leg+" -> "+targets[leg]+" at "+body.position);File.WriteAllLines("Design/DrownedGrove/WalkTest.txt",results);leg++;if(leg==targets.Length){Finish("PASS complete loop, WASD + arrows, camera follow Z unchanged; frames="+frames);return;}Plan();}
 if(now-lastProgress>7||now-begin>220)Finish("FAIL stalled leg "+leg+" body="+body.position+" target="+(index<path.Count?path[index]:targets[leg]));}
 static void Finish(string result){InputSystem.onAfterUpdate-=Input;EditorApplication.update-=Tick;if(keyboard!=null){InputState.Change(keyboard,new KeyboardState());InputSystem.RemoveDevice(keyboard);keyboard=null;}if(body){body.linearVelocity=Vector2.zero;body.position=original;player.position=original;}foreach(var e in encounters)if(e)e.enabled=true;if(spawner)spawner.enabled=true;results.Add(result);File.WriteAllLines("Design/DrownedGrove/WalkTest.txt",results);}
}
